(function(){const fs=require("fs"),basePath="HOLO/CARAVAN/";let menuModule=0,gameModule=0,resultModule=0,timer=0,removed=0,ante=50,funds=500,opponentFunds=500,opponent="",savedIdleTimeout=0,idleDisabled=0;function clearTimer(){if(timer){clearTimeout(timer);timer=0}}function reclaim(){process.memory(true);E.defrag()}function disableIdle(){if(idleDisabled)return;savedIdleTimeout=Pip.settings?Pip.settings.idleTimeout:0;if(Pip.settings)Pip.settings.idleTimeout=0;if(Pip.timers&&Pip.timers.idle){clearTimeout(Pip.timers.idle);delete Pip.timers.idle}idleDisabled=1}function restoreIdle(){if(!idleDisabled)return;if(Pip.settings)Pip.settings.idleTimeout=savedIdleTimeout;idleDisabled=0;if(!Pip.sleeping&&Pip.kickIdleTimer){try{Pip.kickIdleTimer()}catch(idleError){}}}function unloadMenu(){if(menuModule&&menuModule.remove)menuModule.remove();menuModule=0}function unloadGame(){if(gameModule)gameModule[0]();gameModule=0}function unloadResult(){if(resultModule&&resultModule.remove)resultModule.remove();resultModule=0}function loadMenu(){let sourceCode=0,factory=0;if(removed)return;restoreIdle();unloadMenu();reclaim();sourceCode=fs.readFileSync(basePath+"CARAVAN_MENU_INTERFACE.MIN.JS");factory=eval(sourceCode);sourceCode=0;menuModule=factory({fs:fs,basePath:basePath,screen:0,menuSelection:0,ante:ante,funds:funds,opponentFunds:opponentFunds,opponent:opponent,resultOutcome:"DRAW",resultDelta:0,onStartGame:requestGame});factory=0;h.flip();Pip.lastFlip=getTime()}function requestGame(state){if(removed)return;ante=state.ante;funds=state.funds;if(state.opponentFunds!==undefined)opponentFunds=state.opponentFunds;opponent=state.opponent||opponent;clearTimer();timer=setTimeout(beginGame,1)}function beginGame(){let sourceCode=0,factory=0;timer=0;if(removed)return;unloadMenu();disableIdle();reclaim();sourceCode=fs.readFileSync(basePath+"CARAVAN_GAME.MIN.JS");factory=eval(sourceCode);sourceCode=0;gameModule=factory([fs,basePath,opponent,finishGame]);factory=0}function ensureResult(){let sourceCode=0,factory=0;if(resultModule)return 1;sourceCode=fs.readFileSync(basePath+"CARAVAN_RESULT_MENU.MIN.JS");factory=eval(sourceCode);sourceCode=0;resultModule=factory({fs:fs,basePath:basePath});factory=0;return resultModule?1:0}function finishGame(outcome){let delta=0,maxAnte=0;if(removed)return;if(outcome==="PLAYER"){delta=ante;funds+=ante;opponentFunds-=ante;if(opponentFunds<0)opponentFunds=0}else if(outcome==="CPU"){delta=-ante;funds-=ante;if(funds<0)funds=0;opponentFunds+=ante}maxAnte=funds<opponentFunds?funds:opponentFunds;if(funds<10||maxAnte<10)ante=0;else if(ante>maxAnte)ante=maxAnte;clearTimer();timer=setTimeout(function(){timer=0;if(removed||!gameModule)return;if(!ensureResult())return;resultModule.show({outcome:outcome,delta:delta,opponent:opponent,funds:funds,opponentFunds:opponentFunds,onRematch:rematch,onNewOpponent:rematch,onBack:resultBack})},8)}function rematch(n){let maxAnte=0;if(removed||!gameModule||funds<10)return;if(n){opponent=n;opponentFunds=500}else if(opponentFunds<10)return;maxAnte=funds<opponentFunds?funds:opponentFunds;if(maxAnte<10)return;if(ante<10)ante=Math.min(50,maxAnte);else if(ante>maxAnte)ante=maxAnte;timer=setTimeout(function(){timer=0;if(removed||!gameModule)return;unloadResult();reclaim();gameModule[1](n)},1)}function resultBack(){unloadResult();unloadGame();restoreIdle();reclaim();clearTimer();timer=setTimeout(function(){timer=0;loadMenu()},1)}function remove(){if(removed)return;removed=1;clearTimer();unloadMenu();unloadGame();unloadResult();restoreIdle();reclaim()}loadMenu();return{id:"CARAVAN",notDefault:true,fullscreen:true,remove:remove}})
